    if not prefs.achievements_ids['TO_THE_MOON'] then prefs.achievements_ids['TO_THE_MOON'] = {}; end;
    if not prefs.achievements_ids['TREATS_FROM_MOTHER'] then prefs.achievements_ids['TREATS_FROM_MOTHER'] = {}; end;
    if not prefs.achievements_ids['TUT_QUEST_DONE'] then prefs.achievements_ids['TUT_QUEST_DONE'] = {}; end;
    if not prefs.achievements_ids['VALOR_AND_LUCK'] then prefs.achievements_ids['VALOR_AND_LUCK'] = {}; end;
    if not prefs.achievements_ids['WOLF_NEEDS_IT_MORE'] then prefs.achievements_ids['WOLF_NEEDS_IT_MORE'] = {}; end;
    if not prefs.achievements_ids['WOLF_TALE'] then prefs.achievements_ids['WOLF_TALE'] = {}; end;
