-- 113
v_f7526f95_1fa6_4053_9d1d_197169fbcc94 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '113',
    bgimg = function(s)
        if (true) then
            return 'images/add_113.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Примчались дровосеки на опушку и увидели там напуганную старушку. Один из мужиков спросил:");
pn();
pn("– Кто вы? Что вы здесь делаете? Вам помочь? Вас кто-то напугал?");
pn();
pn("Бабка, увидев здоровых мужиков с топорами, попятилась назад повторяя:");
pn();
pn("– Забирайте корзинку и деньги, я не против! Только отпустите!");
pn();
pn("– Не бойтесь! – с улыбкой сказал дровосек, – мы вас не обидим.");
pn();
pn("Без слухового аппарата, бабка не могла расслышать что говорят дровосеки. Но она видела оскаленную рожу и продолжала твердить:");
pn();
pn("– Забирайте корзинку и деньги, я не против! Только отпустите!");
pn();
pn("– Ладно, пойдём отсюда, друг! -- обратился один дровосек к другому. И они пошли прочь. Когда дровосеки скрылись из виду, бабка облегчённо вздохнула.");
pn();
