-- 22
v_2829ffed_aa2f_4093_ba19_955aebf7bfe3 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '22',
    bgimg = function(s)
        if (true) then
            return 'images/add_22.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Вскоре девочка пришла в себя. Она не могла понять где находится и кто все эти люди. Заметив, что девочка очнулась, жена дровосека поспешила заговорить с ней:");
pn();
pn("– Мой муж дровосек нашёл тебя в снегу. Теперь ты у нас дома. Как тебя зовут? И что ты делала в лесу в такую метель? – спросила женщина, протягивая девочке чашку чая.");
pn();
pn("– Я Красная Шапочка. Шла к бабушке и несла ей пирожки и горшочек масла, – ответила девочка, с удовольствием попивая горячий напиток.");
pn();
pn("– А где живёт твоя бабушка?");
pn();
pn("– На опушке леса.");
pn();
pn("– Совсем недалеко отсюда! – воскликнула жена дровосека, – а мы и не знали что поблизости есть ещё чей-то домик.");
pn();
pn("Когда метель закончилась, дровосек хотел проводить Красную Шапочку домой, но она сказала, что должна навестить бабушку.");
pn();
    end,
    walk_to = "v_2829ffed_aa2f_4093_ba19_955aebf7bfe3_choices",
    autos = function(s)
