-- 158
v_37ad0ba8_4008_4855_91ed_b132f43fedad = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '158',
    bgimg = function(s)
        if (true) then
            return 'images/add_158.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Шла бабка, шла и вдруг на тропинку прямо перед ней вышел Волк.");
pn();
pn("– Здрасьте! Как вас зовут и куда вы идёте? – спросил Волк.");
pn();
pn("– Я бабка, иду в гости к родственникам, – ответила старушка, которая плохо видела без очков и подумала, что разговаривает с низкорослым волосатым мужчиной.");
pn();
pn("– А я Волк.");
pn();
pn("– Какое интересное у вас имя, – сказала бабка, стараясь казаться вежливой, ведь этот мужчина являлся в её глазах потенциальным женихом для матери Красной Шапочки.");
pn();
pn("– А где живут ваши родственники? – поинтересовался Волк.");
pn();
pn("В этот момент у бабки забарахлил слуховой аппарат и ей послышалось \"жуют\" вместо \"живут\".");
pn();
pn("– Ну, где, у себя дома, – ответила старушка, немного удивившись вопросу.");
pn();
pn("– Где расположен их дом? – как бы между прочим спросил Волк.");
pn();
pn("И вновь из-за проблем со слуховым аппаратом бабка расслышала: \"Где жених?\"");
pn();
pn("На несколько секунд она задумалась, после чего ответила:");
pn();
pn("– У моей дочери пока нет жениха. А у вас есть девушка?");
pn();
pn("Волк удивлённо посмотрел на бабку и зачем-то ответил:");
pn();
pn("–  Да.");
pn();
pn("– Жаль, – вздохнула бабка, – то есть поздравляю, всего вам хорошего. Собеседник более не представлял для старушки интереса, поэтому она поправила шляпку и пошла дальше.");
pn();
pn(" Волк стоял на тропинке, с недоумением глядя бабке вслед. Он так и не смог получить от неё нужную информацию, но ему в голову пришла идея проследить за старушкой, которая, как известно, направлялась к дому полному родственников.");
pn();
pn("");
pn();
