-- 93
v_86155a59_0441_4b36_aced_b7ccdb1bb6b0 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '93',
    bgimg = function(s)
        if (true) then
            return 'images/add_93.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Решила мать не тратить время на укутывание. Женщина просто взяла гостинцы и пошла. На улице оказалось гораздо холоднее, чем она ожидала.");
pn();
pn(" Преодолев только половину пути, мать почувствовала, что сильно замёрзла. Неожиданно, она заметила впереди огонёк. Подойдя ближе, мать увидела дровосека, сидящего у костра.");
pn();
pn("");
pn();
pn("– Здравствуйте, месье. Позвольте немного погреться у огня, – проговорила мать.");
pn();
pn("– Добрый день, мадам. Пожалуйста, присаживайтесь рядом со мной на бревно. Устроившись рядом с дровосеком, мать сразу ощутила приятное тепло, идущее от костра.");
pn();
pn("– Позвольте в благодарность угостить вас пирожком, – сказала мать и полезла в корзинку.");
pn();
pn("– Спасибо, не откажусь, – ответил дровосек. Получив пирог, мужчина разогрел его над огнём и принялся за еду.");
pn();
pn(" Пирожок оказался очень вкусный и дровосек спросил у путницы как её зовут и куда она идёт. Пока мать рассказывала о себе и о цели своего путешествия, дровосек украдкой поглядывал на женщину, но мог видеть только её глаза, так как нижнюю часть лица закрывал шарф. Но глаза были красивые и голос приятный.");
pn();
pn("");
pn();
