-- 46
v_4b546dfd_0d48_4dda_b7a4_b5806ab6c712 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '46',
    bgimg = function(s)
        if (true) then
            return 'images/add_46.png';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Пришли они в волчье логово. Правнук Волка взял со стола небольшой листок бумаги и протянул его Красной Шапочке.");
pn();
pn(" Это был список желаний. Все пункты, кроме первого, были зачёркнуты. Девушка прочла верхнюю строку: \"... на луну вместе с Красной Шапочкой\".");
pn();
pn("");
pn();
pn("– Это странно и невозможно! – сказал правнук Волка.");
pn();
pn("Красная Шапочка была удивлена не меньше. Тем не менее она ещё раз перечитала первое предложение, внимательно рассмотрела листок бумаги на котором оно было написано и, наконец, произнесла:");
pn();
pn("– Тут предложение начинается с маленькой буквы и верхний левый уголок оторван. Откуда этот листок?");
pn();
pn("– Из блокнота, – ответил правнук Волка и, открыв средний ящик комода, принялся рыться в ворохе каких-то красных бумажек.");
pn();
pn(" Несколько штук упали на пол. Красная Шапочка увидела, что это маленькие шапочки, совсем как у неё, только сделанные из красной цветной бумаги.");
pn();
pn("");
pn();
pn("– Все эти шапочки сделал Волк, – сообщил его правнук и через несколько секунд воскликнул: – А вот и блокнот из которого Волк вырвал листок!");
pn();
pn("Красная Шапочка просмотрела блокнот и нашла место, откуда был вырван листок. На кусочке бумаги, оставшемся в блокноте, девочка увидела слово \"Повыть\".");
pn();
pn(" Подставив листок к кусочку, оставшемуся в блокноте, Шапочка прочитала: \"Повыть на луну вместе с Красной Шапочкой\".");
pn();
pn("");
pn();
    end,
