        nlb:revive();
        nlb:ways_chk(s);
        if ((_back2shelf)) then         nlb:nlbwalk(v_0d32d6f2_a9dc_4391_aaca_1816be310321, v_fffb151d_fef5_4450_b570_ecec3b2abdde); 

        return false;
 end;
        if ((_abandonQuestCmd and not _abandonQuest)) then     _vl_c864e1eb_f16d_4a9c_b881_7f3b82c6e2b9_0d32d6f2_a9dc_4391_aaca_1816be310321 =  true ;
        nlb:nlbwalk(v_0d32d6f2_a9dc_4391_aaca_1816be310321, v_c864e1eb_f16d_4a9c_b881_7f3b82c6e2b9); 

        return false;
 end;
        return true;
    end,
    nextsnd = function(s)
        local sndfile = nlb:pop('v_0d32d6f2_a9dc_4391_aaca_1816be310321_snds');
        if sndfile ~= nil then
            s.sndout(s);
            add_sound(sndfile);
        end;
    end,
    theme_file = function(s)
        return 'theme_vn.lua';
    end,
    enter = function(s, f)
        nlb:theme_switch(s:theme_file());
        s.lasttext = nil;
        s.wastext = false;
        if not (f.autowired) then
_go2pep =  false ;
        end;
        s:initf();
    end,
    initf = function(s)
        s.snd(s);
        vn:request_full_clear();
        vn:lock_direct();
        local bg_img = s.bgimg(s);
        nlb:revive();
        nlb:ways_chk(s);
        vn:scene(bg_img);
        local geomFuncNeedToCall = true;
        if v_261feb7f_4a3f_4de6_9c8e_943186057f99.preload then
            geomFuncNeedToCall = false;
            v_261feb7f_4a3f_4de6_9c8e_943186057f99:preload(s);
        else
            vn:gshow(v_261feb7f_4a3f_4de6_9c8e_943186057f99);
        end
        if v_e0511981_6fa1_4c27_ad42_47cae3b2c113.preload then
            geomFuncNeedToCall = false;
            v_e0511981_6fa1_4c27_ad42_47cae3b2c113:preload(s);
        else
            vn:gshow(v_e0511981_6fa1_4c27_ad42_47cae3b2c113);
        end
        if v_0b1d97f7_003b_4c2c_8ee3_4b5ff1c9c54b.preload then
            geomFuncNeedToCall = false;
            v_0b1d97f7_003b_4c2c_8ee3_4b5ff1c9c54b:preload(s);
        else
            vn:gshow(v_0b1d97f7_003b_4c2c_8ee3_4b5ff1c9c54b);
        end
        if geomFuncNeedToCall then
            vn:auto_geom('dissolve', function() s.autos(s); end);
        end;
        return 0, 0, vn.scr_w, vn.scr_h;
    end,
    exit = function(s, t)
        s.sndout(s);
        s.wastext = false;
        s.lasttext = nil;
        vn:request_full_clear();
        vn:unlock_direct();
    end,
    life = function(s)
        if vn.stopped then s.autos(s); end;
    end,
    snd = function(s) 
    end,
    sndout = function(s) end,
};

