-- Кидает в дровосека 90
v_c54a5643_05fa_41dd_9d87_675215407476 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = 'Кидает в дровосека 90',
    bgimg = function(s)
        if (true) then
            return 'images/add_90.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Несколько раз оглянувшись назад и не увидев погони, мать остановилась. Только она отдышалась и собралась идти дальше, как на тропинку вышел дровосек.");
pn();
pn("– Добрый день, мадам, – учтиво поприветствовал женщину дровосек.");
pn();
pn("– И вам того же, – ответила мать, насторожившись.");
pn();
pn("– Куда вы путь держите? – поинтересовался мужчина.");
pn();
pn("– Иду в гости к родственнице, несу пирожки и горшочек масла.");
pn();
pn("– Не угостите меня пирожком? – спросил дровосек для поддержания беседы. Он надеялся поближе познакомиться с симпатичной путницей.");
pn();
pn("\"Зубы заговаривает, может он грабитель? Нельзя терять бдительность\", – подумала мать.");
pn();
