-- Концовка 6  34
v_ebc531ce_ada8_423d_ac1b_4053b8f94900 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = 'Концовка 6  34',
    bgimg = function(s)
        if (true) then
            return 'images/add_34.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Наступила неловкая пауза, которую прервал стук в дверь. Бабка пошла открывать. На пороге стоял дровосек.");
pn();
pn("– Здравствуйте, мадам. Я забыл дома свой обед и даже фляжку с водой, а рабочий день в самом разгаре. Не дадите ли вы мне чего-нибудь попить?");
pn();
pn("– Конечно, конечно. Сейчас, – сказала бабка и полезла в шкаф за кружкой. В этот момент дровосек заметил пирожки на столе.");
pn();
pn("– О, любезная мадам, угостите меня, пожалуйста, вашими пирогами. Бабка не знала что ответить. Если сказать правду, он может не поверить и подумает, что ей жалко.");
pn();
pn(" Если не говорить ничего, дровосек может обидеться, что его не предупредили. В итоге, бабка просто махнула рукой.");
pn();
pn(" Приняв этот неопределённый жест за приглашение, дровосек подсел к столу. Не дождавшись, пока принесут чай, мужчина с аппетитом принялся за угощение. Видя, как дровосек уминает пирожки, бабка не смогла сдержаться и засмеялась:");
pn();
pn("");
pn();
pn("– Аха-ха!");
pn();
pn("Мужик не понял что смешного и списал эту странность на возраст. Он быстро всё съел и выпил, а после сказал:");
pn();
pn("– Спасибо, очень вкусно!");
pn();
pn("– Пожалуйста, – в один голос ответили бабка с внучкой и переглянулись. Дровосек взял с собой немного воды и, пообещав что завтра вернёт кувшинчик, ушёл.");
pn();
pn("");
pn();
pn("Достигнута концовка: \"Утилизатор пирожков\".");
pn();
    end,
