-- 45
v_be00c727_db07_46db_a4d3_7fef1e23b440 = vnr {
    nam = 'Return of Red Riding Hood : New Adventures',
    notes = '45',
    bgimg = function(s)
        if (true) then
            return 'images/add_45.jpg';
        end

    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
pn("Прошло десять лет. Красная Шапочка по-прежнему жила в домике в лесу. Как-то раз она пошла в лес пособирать ягод и встретила Волка.");
pn();
pn(" Несколько секунд они молча смотрели друг на друга. Волк первым нарушил молчание. Взглянув на головной убор девушки, он спросил:");
pn();
pn("");
pn();
pn("– Это ты Красная Шапочка?");
pn();
pn("– Да.");
pn();
pn("– Наконец-то я тебя нашёл, – облегчённо вздохнул Волк.");
pn();
pn("– Откуда ты меня знаешь? – удивилась Красная Шапочка. – А-а, ты один из тех волчат, которых я когда-то угостила пирожками!");
pn();
pn("Волк заморгал от удивления, пытаясь сообразить, что имеет в виду Красная Шапочка. Наконец, он просто ответил:");
pn();
pn("– Нет. Я один из правнуков того Волка, с которым вы когда-то катались с горки. Он  совсем старый стал.");
pn();
pn(" Вот попросил нас исполнить парочку его желаний. Мы не могли отказать и выполнили их все, кроме одного, самого главного.");
pn();
pn(" В этом желании упоминается твоё имя, поэтому без тебя мы не справимся. Не могла бы ты пойти со мной и помочь в этом деле?");
pn();
pn("");
pn();
pn("Волк посмотрел на Шапочку внимательным пристальным взглядом. В нём девушка прочла явную просьбу о помощи.");
pn();
pn(" Красная Шапочка задумалась. В памяти всплыли яркие мгновения, проведённые с Волком на ледяной горке. Долее не колеблясь, Красная Шапочка согласилась.");
pn();
pn("");
pn();
